window.EXERCISE_BANK = [["sql1", "sql", "debutant", "Ma première table", "Crée une table `livres` avec quatre colonnes : `id` (INTEGER), `titre` (TEXT), `auteur` (TEXT) et `annee` (INTEGER).", "-- Crée la table livres\n", "CREATE TABLE livres (\n    id INTEGER,\n    titre TEXT,\n    auteur TEXT,\n    annee INTEGER\n);", "Chaque colonne s'écrit `nom TYPE`, séparée de la suivante par une virgule."],["sql2", "sql", "debutant", "Contraintes sur les colonnes", "Crée une table `joueurs` : `id` est la clé primaire (INTEGER), `pseudo` est un TEXT obligatoire (NOT NULL) et `score` est un INTEGER qui vaut 0 par défaut.", "-- Crée la table joueurs\n", "CREATE TABLE joueurs (\n    id INTEGER PRIMARY KEY,\n    pseudo TEXT NOT NULL,\n    score INTEGER DEFAULT 0\n);", "Les contraintes se placent après le type : `PRIMARY KEY`, `NOT NULL`, `DEFAULT 0`."],["sql3", "sql", "intermediaire", "Deux tables reliées", "Crée la table `auteurs(id, nom)` puis la table `livres(id, titre, auteur_id)`. La colonne `auteur_id` de `livres` doit être une clé étrangère qui référence `auteurs(id)`.", "-- Crée les tables auteurs puis livres\n", "CREATE TABLE auteurs (\n    id INTEGER PRIMARY KEY,\n    nom TEXT\n);\n\nCREATE TABLE livres (\n    id INTEGER PRIMARY KEY,\n    titre TEXT,\n    auteur_id INTEGER,\n    FOREIGN KEY (auteur_id) REFERENCES auteurs(id)\n);", "Ajoute en dernière ligne de `livres` : `FOREIGN KEY (colonne) REFERENCES table(colonne)`."],["sql4", "sql", "debutant", "Ajouter un élève", "Table `eleves(id, nom, age, classe, moyenne)`. Ajoute l'élève Barbara : id 7, 17 ans, classe `Terminale A`, moyenne 16.0.", "-- Ajoute Barbara dans la table eleves\n", "INSERT INTO eleves VALUES (7, 'Barbara', 17, 'Terminale A', 16.0);", "`INSERT INTO table VALUES (...)` : les valeurs suivent l'ordre des colonnes, le texte est entre apostrophes."],["sql5", "sql", "debutant", "Plusieurs lignes d'un coup", "La table `fruits(nom, prix)` est vide. Ajoute en une seule instruction INSERT : pomme à 1.2, poire à 1.5 et kiwi à 0.8.", "-- Remplis la table fruits\n", "INSERT INTO fruits VALUES ('pomme', 1.2), ('poire', 1.5), ('kiwi', 0.8);", "Sépare les groupes de valeurs par des virgules : `VALUES (...), (...)`."],["sql6", "sql", "intermediaire", "Corriger une note", "Table `eleves(id, nom, age, classe, moyenne)`. Alan a été mal noté : sa moyenne passe à 10.5. Les autres élèves ne doivent pas changer.", "-- Modifie la moyenne d'Alan\n", "UPDATE eleves SET moyenne = 10.5 WHERE nom = 'Alan';", "Sans `WHERE`, UPDATE modifie toutes les lignes de la table."],["sql7", "sql", "intermediaire", "Supprimer avec précision", "Table `eleves(id, nom, age, classe, moyenne)`. Supprime les élèves dont la moyenne est strictement inférieure à 12.", "-- Supprime les élèves en difficulté\n", "DELETE FROM eleves WHERE moyenne < 12;", "`DELETE FROM table WHERE condition;` Attention : Linus a exactement 12."],["sql8", "sql", "debutant", "Tout afficher", "Table `eleves(id, nom, age, classe, moyenne)`. Affiche toutes les colonnes de tous les élèves.", "-- Affiche toute la table eleves\n", "SELECT * FROM eleves;", "L'étoile `*` signifie « toutes les colonnes »."],["sql9", "sql", "debutant", "Choisir des colonnes", "Table `eleves(id, nom, age, classe, moyenne)`. Affiche uniquement le nom et la moyenne de chaque élève, dans cet ordre.", "-- Nom et moyenne\n", "SELECT nom, moyenne FROM eleves;", "Liste les colonnes voulues après SELECT, séparées par des virgules."],["sql10", "sql", "debutant", "Filtrer les lignes", "Table `eleves(id, nom, age, classe, moyenne)`. Affiche le nom des élèves de la classe `Terminale A`.", "-- Élèves de Terminale A\n", "SELECT nom FROM eleves WHERE classe = 'Terminale A';", "`WHERE colonne = 'texte'` : le texte se met entre apostrophes."],["sql11", "sql", "intermediaire", "Trier les résultats", "Table `eleves(id, nom, age, classe, moyenne)`. Affiche le nom et la moyenne de chaque élève, du meilleur au moins bon.", "-- Classement par moyenne\n", "SELECT nom, moyenne FROM eleves ORDER BY moyenne DESC;", "`ORDER BY colonne DESC` trie du plus grand au plus petit."],["sql12", "sql", "intermediaire", "Plusieurs conditions", "Table `eleves(id, nom, age, classe, moyenne)`. Affiche le nom des élèves qui ont 17 ans et une moyenne d'au moins 12.", "-- 17 ans et moyenne >= 12\n", "SELECT nom FROM eleves WHERE age = 17 AND moyenne >= 12;", "Combine les conditions avec `AND`."],["sql13", "sql", "intermediaire", "Compter", "Table `eleves(id, nom, age, classe, moyenne)`. Affiche le nombre d'élèves de la classe `Terminale B`.", "-- Combien d'élèves en Terminale B ?\n", "SELECT COUNT(*) FROM eleves WHERE classe = 'Terminale B';", "`COUNT(*)` compte les lignes qui passent le filtre WHERE."],["sql14", "sql", "difficile", "Moyenne par classe", "Table `eleves(id, nom, age, classe, moyenne)`. Affiche chaque classe avec la moyenne de ses élèves, arrondie à 2 décimales avec `ROUND`, triée par nom de classe.", "-- Moyenne de chaque classe\n", "SELECT classe, ROUND(AVG(moyenne), 2) FROM eleves GROUP BY classe ORDER BY classe;", "`GROUP BY classe` regroupe les lignes, puis `AVG` calcule une moyenne par groupe."],["sql15", "sql", "intermediaire", "Ma première jointure", "Tables `auteurs(id, nom)` et `livres(id, titre, annee, auteur_id)`. Affiche le titre de chaque livre avec le nom de son auteur.", "-- Titre et auteur de chaque livre\n", "SELECT livres.titre, auteurs.nom\nFROM livres\nJOIN auteurs ON livres.auteur_id = auteurs.id;", "`JOIN auteurs ON livres.auteur_id = auteurs.id` relie la clé étrangère à la clé primaire."],["sql16", "sql", "difficile", "Jointure et filtre", "Tables `auteurs(id, nom)` et `livres(id, titre, annee, auteur_id)`. Affiche le titre des livres écrits par Camus.", "-- Livres de Camus\n", "SELECT livres.titre\nFROM livres\nJOIN auteurs ON livres.auteur_id = auteurs.id\nWHERE auteurs.nom = 'Camus';", "Fais la jointure, puis filtre avec `WHERE auteurs.nom = 'Camus'`."],["sql17", "sql", "difficile", "Respecter la clé étrangère", "Tables `auteurs(id, nom)` et `livres(id, titre, annee, auteur_id)`. Ajoute l'auteur Zola (id 4) puis son livre Germinal (id 5, année 1885). Les clés étrangères sont activées : l'ordre des insertions compte.", "-- Ajoute Zola puis Germinal\n", "INSERT INTO auteurs VALUES (4, 'Zola');\nINSERT INTO livres VALUES (5, 'Germinal', 1885, 4);", "Un livre ne peut référencer qu'un auteur qui existe déjà : insère l'auteur en premier."],["sql18", "sql", "difficile", "Livres par auteur", "Tables `auteurs(id, nom)` et `livres(id, titre, annee, auteur_id)`. Affiche chaque auteur avec son nombre de livres, y compris ceux qui n'en ont aucun, du plus grand nombre au plus petit puis par nom.", "-- Nombre de livres par auteur\n", "SELECT auteurs.nom, COUNT(livres.id) AS nb\nFROM auteurs\nLEFT JOIN livres ON livres.auteur_id = auteurs.id\nGROUP BY auteurs.id\nORDER BY nb DESC, auteurs.nom;", "Un `LEFT JOIN` garde les auteurs sans livre. `COUNT(livres.id)` ne compte pas les NULL."],["g1", "bases", "debutant", "Le double", "Écris `double(n)` qui retourne le double de `n`.", "# Le double\ndef double(n):\n    pass  # À toi de jouer !\n", "def double(n):\n    return 2 * n", "Multiplie `n` par 2."], ["g2", "bases", "debutant", "Majeur ?", "`est_majeur(age)` retourne `True` à partir de 18 ans.", "# Majeur ?\ndef est_majeur(age):\n    pass  # À toi de jouer !\n", "def est_majeur(age):\n    return age >= 18", "Une comparaison est déjà un booléen."], ["g3", "bases", "debutant", "Signe", "`signe(n)` retourne la chaîne `positif`, `négatif` ou `nul`.", "# Signe\ndef signe(n):\n    pass  # À toi de jouer !\n", "def signe(n):\n    if n > 0:\n        return \"positif\"\n    if n < 0:\n        return \"négatif\"\n    return \"nul\"", "Trois cas : `if`, `if`, puis `return`."], ["g4", "bases", "debutant", "Le plus grand", "`plus_grand(a, b)` retourne le maximum de deux nombres, sans `max`.", "# Le plus grand\ndef plus_grand(a, b):\n    pass  # À toi de jouer !\n", "def plus_grand(a, b):\n    if a > b:\n        return a\n    return b", "Compare `a` et `b`."], ["g5", "bases", "debutant", "Celsius vers Fahrenheit", "`fahrenheit(c)` : F = C × 9 / 5 + 32, en division entière `//`.", "# Celsius vers Fahrenheit\ndef fahrenheit(c):\n    pass  # À toi de jouer !\n", "def fahrenheit(c):\n    return c * 9 // 5 + 32", "Multiplie, divise, puis ajoute 32."], ["g6", "bases", "intermediaire", "Somme des chiffres", "`somme_chiffres(n)` retourne la somme des chiffres de l'entier `n >= 0`.", "# Somme des chiffres\ndef somme_chiffres(n):\n    pass  # À toi de jouer !\n", "def somme_chiffres(n):\n    t = 0\n    while n > 0:\n        t += n % 10\n        n //= 10\n    return t", "`n % 10` donne le dernier chiffre, `n // 10` l'enlève."], ["g7", "bases", "intermediaire", "FizzBuzz", "`fizzbuzz(n)` : `FizzBuzz` si multiple de 15, `Fizz` si de 3, `Buzz` si de 5, sinon `str(n)`.", "# FizzBuzz\ndef fizzbuzz(n):\n    pass  # À toi de jouer !\n", "def fizzbuzz(n):\n    if n % 15 == 0:\n        return \"FizzBuzz\"\n    if n % 3 == 0:\n        return \"Fizz\"\n    if n % 5 == 0:\n        return \"Buzz\"\n    return str(n)", "Teste d'abord le multiple de 15."], ["g8", "bases", "intermediaire", "Année bissextile", "`est_bissextile(a)` : divisible par 4, sauf les siècles, sauf ceux divisibles par 400.", "# Année bissextile\ndef est_bissextile(a):\n    pass  # À toi de jouer !\n", "def est_bissextile(a):\n    return a % 400 == 0 or (a % 4 == 0 and a % 100 != 0)", "Combine `and` / `or` avec des parenthèses."], ["g9", "bases", "intermediaire", "Nombre premier", "`est_premier(n)` retourne `True` si `n` n'a pas d'autre diviseur que 1 et lui-même.", "# Nombre premier\ndef est_premier(n):\n    pass  # À toi de jouer !\n", "def est_premier(n):\n    if n < 2:\n        return False\n    for d in range(2, int(n ** 0.5) + 1):\n        if n % d == 0:\n            return False\n    return True", "Teste les diviseurs jusqu'à √n."], ["g10", "bases", "intermediaire", "PGCD", "`pgcd(a, b)` par l'algorithme d'Euclide.", "# PGCD\ndef pgcd(a, b):\n    pass  # À toi de jouer !\n", "def pgcd(a, b):\n    while b != 0:\n        a, b = b, a % b\n    return a", "Remplace `(a, b)` par `(b, a % b)` tant que `b != 0`."], ["g11", "bases", "difficile", "Syracuse", "`syracuse(n)` : nombre d'étapes pour atteindre 1 (pair : `n//2`, impair : `3n+1`).", "# Syracuse\ndef syracuse(n):\n    pass  # À toi de jouer !\n", "def syracuse(n):\n    e = 0\n    while n != 1:\n        n = n // 2 if n % 2 == 0 else 3 * n + 1\n        e += 1\n    return e", "Une boucle `while` avec un compteur."], ["g12", "listes", "debutant", "Somme", "`somme(l)` retourne la somme des éléments, sans `sum`.", "# Somme\ndef somme(l):\n    pass  # À toi de jouer !\n", "def somme(l):\n    t = 0\n    for x in l:\n        t += x\n    return t", "Accumule dans une variable initialisée à 0."], ["g13", "listes", "debutant", "Contient", "`contient(l, x)` retourne `True` si `x` est dans `l`, avec une boucle.", "# Contient\ndef contient(l, x):\n    pass  # À toi de jouer !\n", "def contient(l, x):\n    for e in l:\n        if e == x:\n            return True\n    return False", "Retourne `True` dès que tu trouves `x`."], ["g14", "listes", "debutant", "Compter les pairs", "`nb_pairs(l)` retourne le nombre d'éléments pairs.", "# Compter les pairs\ndef nb_pairs(l):\n    pass  # À toi de jouer !\n", "def nb_pairs(l):\n    n = 0\n    for x in l:\n        if x % 2 == 0:\n            n += 1\n    return n", "Un compteur et le test `x % 2 == 0`."], ["g15", "listes", "intermediaire", "Inverser", "`inverser(l)` retourne une NOUVELLE liste inversée (sans `reverse` ni `[::-1]`).", "# Inverser\ndef inverser(l):\n    pass  # À toi de jouer !\n", "def inverser(l):\n    r = []\n    for x in l:\n        r.insert(0, x)\n    return r", "`insert(0, x)` ajoute au début."], ["g16", "listes", "intermediaire", "Sans doublons", "`sans_doublons(l)` retourne la liste sans répétitions, dans l'ordre d'apparition.", "# Sans doublons\ndef sans_doublons(l):\n    pass  # À toi de jouer !\n", "def sans_doublons(l):\n    r = []\n    for x in l:\n        if x not in r:\n            r.append(x)\n    return r", "N'ajoute `x` que s'il n'est pas déjà dans `r`."], ["g17", "listes", "intermediaire", "Fusion de listes triées", "`fusion(a, b)` fusionne deux listes triées en une liste triée.", "# Fusion de listes triées\ndef fusion(a, b):\n    pass  # À toi de jouer !\n", "def fusion(a, b):\n    i = j = 0\n    r = []\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:\n            r.append(a[i])\n            i += 1\n        else:\n            r.append(b[j])\n            j += 1\n    return r + a[i:] + b[j:]", "Un indice par liste ; recopie le reste à la fin."], ["g18", "listes", "difficile", "Rotation", "`rotation(l, k)` décale les éléments de `k` rangs vers la droite (circulaire).", "# Rotation\ndef rotation(l, k):\n    pass  # À toi de jouer !\n", "def rotation(l, k):\n    if not l:\n        return []\n    k %= len(l)\n    return l[len(l) - k:] + l[:len(l) - k]", "Découpe en deux avec les tranches et recolle."], ["g19", "listes", "difficile", "Plus longue suite croissante", "`plus_longue_croissante(l)` : longueur de la plus longue suite d'éléments consécutifs strictement croissants.", "# Plus longue suite croissante\ndef plus_longue_croissante(l):\n    pass  # À toi de jouer !\n", "def plus_longue_croissante(l):\n    if not l:\n        return 0\n    best = cur = 1\n    for i in range(1, len(l)):\n        cur = cur + 1 if l[i] > l[i - 1] else 1\n        best = max(best, cur)\n    return best", "Garde la longueur de la suite en cours et le meilleur score."], ["g20", "stats", "debutant", "Moyenne", "`moyenne(l)` retourne la moyenne arrondie à 2 décimales (`round`).", "# Moyenne\ndef moyenne(l):\n    pass  # À toi de jouer !\n", "def moyenne(l):\n    return round(sum(l) / len(l), 2)", "`round(x, 2)` arrondit à 2 décimales."], ["g21", "stats", "intermediaire", "Min et max", "`min_max(l)` retourne la liste `[minimum, maximum]`, sans `min` ni `max`.", "# Min et max\ndef min_max(l):\n    pass  # À toi de jouer !\n", "def min_max(l):\n    mn = mx = l[0]\n    for x in l:\n        if x < mn:\n            mn = x\n        if x > mx:\n            mx = x\n    return [mn, mx]", "Initialise `mn` et `mx` avec le premier élément."], ["g22", "stats", "difficile", "Médiane", "`mediane(l)` : valeur centrale (moyenne des deux centrales si la taille est paire).", "# Médiane\ndef mediane(l):\n    pass  # À toi de jouer !\n", "def mediane(l):\n    s = sorted(l)\n    m = len(s) // 2\n    return s[m] if len(s) % 2 else (s[m - 1] + s[m]) / 2", "Trie d'abord, puis regarde le milieu."], ["g23", "comprehension", "debutant", "Doubles", "`doubles(l)` retourne les doubles, en une ligne (compréhension).", "# Doubles\ndef doubles(l):\n    pass  # À toi de jouer !\n", "def doubles(l):\n    return [2 * x for x in l]", "`[expression for x in l]`"], ["g24", "comprehension", "debutant", "Garder les pairs", "`garde_pairs(l)` ne garde que les éléments pairs, par compréhension.", "# Garder les pairs\ndef garde_pairs(l):\n    pass  # À toi de jouer !\n", "def garde_pairs(l):\n    return [x for x in l if x % 2 == 0]", "Ajoute `if condition` à la fin."], ["g25", "comprehension", "intermediaire", "Table de multiplication", "`table_mult(n)` retourne la table `n × n` : `[[1×1, 1×2, …], …]`.", "# Table de multiplication\ndef table_mult(n):\n    pass  # À toi de jouer !\n", "def table_mult(n):\n    return [[i * j for j in range(1, n + 1)] for i in range(1, n + 1)]", "Deux compréhensions imbriquées."], ["g26", "comprehension", "difficile", "Aplatir", "`aplatir(m)` transforme une liste de listes en une seule liste.", "# Aplatir\ndef aplatir(m):\n    pass  # À toi de jouer !\n", "def aplatir(m):\n    return [x for ligne in m for x in ligne]", "Deux `for` dans la même compréhension, dans l'ordre de lecture."], ["g27", "texte", "debutant", "Compter une lettre", "`compte_lettre(mot, c)` retourne combien de fois `c` apparaît dans `mot`.", "# Compter une lettre\ndef compte_lettre(mot, c):\n    pass  # À toi de jouer !\n", "def compte_lettre(mot, c):\n    n = 0\n    for l in mot:\n        if l == c:\n            n += 1\n    return n", "Parcours le mot lettre par lettre."], ["g28", "texte", "debutant", "Voyelles", "`nb_voyelles(s)` compte les voyelles `aeiouy` (majuscules comprises).", "# Voyelles\ndef nb_voyelles(s):\n    pass  # À toi de jouer !\n", "def nb_voyelles(s):\n    return len([c for c in s.lower() if c in \"aeiouy\"])", "`s.lower()` évite de traiter les majuscules à part."], ["g29", "texte", "intermediaire", "Palindrome", "`est_palindrome(s)` : se lit pareil dans les deux sens (casse et espaces ignorés).", "# Palindrome\ndef est_palindrome(s):\n    pass  # À toi de jouer !\n", "def est_palindrome(s):\n    s = s.lower().replace(\" \", \"\")\n    return s == s[::-1]", "Nettoie la chaîne, puis compare avec son inverse."], ["g30", "texte", "intermediaire", "Anagrammes", "`sont_anagrammes(a, b)` : mêmes lettres, casse ignorée.", "# Anagrammes\ndef sont_anagrammes(a, b):\n    pass  # À toi de jouer !\n", "def sont_anagrammes(a, b):\n    return sorted(a.lower()) == sorted(b.lower())", "Deux mots anagrammes ont les mêmes lettres une fois triées."], ["g31", "texte", "difficile", "Compression", "`compresser(s)` : `\"aaabcc\"` devient `\"a3b1c2\"`.", "# Compression\ndef compresser(s):\n    pass  # À toi de jouer !\n", "def compresser(s):\n    if not s:\n        return \"\"\n    r = \"\"\n    cur, n = s[0], 1\n    for c in s[1:]:\n        if c == cur:\n            n += 1\n        else:\n            r += cur + str(n)\n            cur, n = c, 1\n    return r + cur + str(n)", "N'oublie pas le dernier groupe après la boucle."], ["g32", "tri", "debutant", "Liste triée ?", "`est_trie(l)` retourne `True` si `l` est triée par ordre croissant.", "# Liste triée ?\ndef est_trie(l):\n    pass  # À toi de jouer !\n", "def est_trie(l):\n    for i in range(len(l) - 1):\n        if l[i] > l[i + 1]:\n            return False\n    return True", "Compare chaque élément à son voisin."], ["g33", "tri", "intermediaire", "Tri par insertion", "`tri_insertion(l)` retourne une copie triée (algorithme d'insertion).", "# Tri par insertion\ndef tri_insertion(l):\n    pass  # À toi de jouer !\n", "def tri_insertion(l):\n    l = l[:]\n    for i in range(1, len(l)):\n        x = l[i]\n        j = i - 1\n        while j >= 0 and l[j] > x:\n            l[j + 1] = l[j]\n            j -= 1\n        l[j + 1] = x\n    return l", "Décale vers la droite les éléments plus grands que `x`."], ["g34", "tri", "intermediaire", "Tri par sélection", "`tri_selection(l)` retourne une copie triée (algorithme de sélection).", "# Tri par sélection\ndef tri_selection(l):\n    pass  # À toi de jouer !\n", "def tri_selection(l):\n    l = l[:]\n    for i in range(len(l)):\n        m = i\n        for j in range(i + 1, len(l)):\n            if l[j] < l[m]:\n                m = j\n        l[i], l[m] = l[m], l[i]\n    return l", "Cherche l'indice du minimum, puis échange."], ["g35", "recherche", "debutant", "Recherche linéaire", "`indice(l, x)` retourne l'indice de la 1re occurrence de `x`, ou `-1`.", "# Recherche linéaire\ndef indice(l, x):\n    pass  # À toi de jouer !\n", "def indice(l, x):\n    for i in range(len(l)):\n        if l[i] == x:\n            return i\n    return -1", "Parcours avec `range(len(l))`."], ["g36", "recherche", "intermediaire", "Dichotomie", "`dicho(l, x)` : `x` est-il dans la liste TRIÉE `l` ? (par dichotomie)", "# Dichotomie\ndef dicho(l, x):\n    pass  # À toi de jouer !\n", "def dicho(l, x):\n    g, d = 0, len(l) - 1\n    while g <= d:\n        m = (g + d) // 2\n        if l[m] == x:\n            return True\n        if l[m] < x:\n            g = m + 1\n        else:\n            d = m - 1\n    return False", "Compare au milieu, puis garde la bonne moitié."], ["g37", "recherche", "difficile", "Première occurrence", "`premiere_occ(l, x)` : indice de la 1re occurrence de `x` dans `l` triée (avec doublons), sinon `-1`, en O(log n).", "# Première occurrence\ndef premiere_occ(l, x):\n    pass  # À toi de jouer !\n", "def premiere_occ(l, x):\n    g, d = 0, len(l)\n    while g < d:\n        m = (g + d) // 2\n        if l[m] < x:\n            g = m + 1\n        else:\n            d = m\n    return g if g < len(l) and l[g] == x else -1", "Si `l[m] >= x`, la réponse est à gauche ou en `m`."], ["g38", "tableaux", "debutant", "Somme d'une colonne", "`somme_colonne(m, j)` retourne la somme de la colonne `j` de la matrice `m`.", "# Somme d'une colonne\ndef somme_colonne(m, j):\n    pass  # À toi de jouer !\n", "def somme_colonne(m, j):\n    return sum(ligne[j] for ligne in m)", "Parcours les lignes et prends `ligne[j]`."], ["g39", "tableaux", "intermediaire", "Transposée", "`transposee(m)` : les lignes deviennent des colonnes.", "# Transposée\ndef transposee(m):\n    pass  # À toi de jouer !\n", "def transposee(m):\n    return [[m[i][j] for i in range(len(m))] for j in range(len(m[0]))]", "Le nouvel élément `[j][i]` vaut `m[i][j]`."], ["g40", "tableaux", "difficile", "Rotation de 90°", "`rotation90(m)` : tourne la matrice d'un quart de tour dans le sens horaire.", "# Rotation de 90°\ndef rotation90(m):\n    pass  # À toi de jouer !\n", "def rotation90(m):\n    return [list(r) for r in zip(*m[::-1])]", "Inverse l'ordre des lignes, puis transpose."], ["g41", "dico", "debutant", "Compter les lettres", "`compte(s)` retourne un dictionnaire `{lettre: nombre d'occurrences}`.", "# Compter les lettres\ndef compte(s):\n    pass  # À toi de jouer !\n", "def compte(s):\n    d = {}\n    for c in s:\n        d[c] = d.get(c, 0) + 1\n    return d", "`d.get(c, 0)` évite l'erreur de clé absente."], ["g42", "dico", "intermediaire", "Grouper par initiale", "`par_initiale(l)` : `{initiale: [mots commençant par elle]}`.", "# Grouper par initiale\ndef par_initiale(l):\n    pass  # À toi de jouer !\n", "def par_initiale(l):\n    d = {}\n    for m in l:\n        d.setdefault(m[0], []).append(m)\n    return d", "`setdefault(cle, [])` crée la liste si besoin."], ["g43", "dico", "difficile", "Élément le plus fréquent", "`le_plus_frequent(l)` retourne l'élément le plus fréquent (pas d'égalité dans les tests).", "# Élément le plus fréquent\ndef le_plus_frequent(l):\n    pass  # À toi de jouer !\n", "def le_plus_frequent(l):\n    c = {}\n    for x in l:\n        c[x] = c.get(x, 0) + 1\n    best = l[0]\n    for x in c:\n        if c[x] > c[best]:\n            best = x\n    return best", "Compte d'abord, puis cherche le maximum dans le dictionnaire."], ["g44", "recursivite", "debutant", "Factorielle", "`fact(n)` : factorielle de `n`, de façon récursive.", "# Factorielle\ndef fact(n):\n    pass  # À toi de jouer !\n", "def fact(n):\n    if n <= 1:\n        return 1\n    return n * fact(n - 1)", "Cas de base : `n <= 1`. Sinon `n * fact(n - 1)`."], ["g45", "recursivite", "intermediaire", "Puissance", "`puissance(a, n)` retourne `a` puissance `n` (récursif, sans `**`).", "# Puissance\ndef puissance(a, n):\n    pass  # À toi de jouer !\n", "def puissance(a, n):\n    if n == 0:\n        return 1\n    return a * puissance(a, n - 1)", "Cas de base : `n == 0`."], ["g46", "recursivite", "intermediaire", "Fibonacci", "`fib(n)` : `fib(0)=0`, `fib(1)=1`, puis somme des deux précédents.", "# Fibonacci\ndef fib(n):\n    pass  # À toi de jouer !\n", "def fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)", "Deux appels récursifs."], ["g47", "recursivite", "difficile", "Somme imbriquée", "`somme_imbriquee(l)` : somme de tous les nombres d'une liste contenant des sous-listes à toute profondeur.", "# Somme imbriquée\ndef somme_imbriquee(l):\n    pass  # À toi de jouer !\n", "def somme_imbriquee(l):\n    t = 0\n    for x in l:\n        if isinstance(x, list):\n            t += somme_imbriquee(x)\n        else:\n            t += x\n    return t", "`isinstance(x, list)` détecte une sous-liste."], ["g48", "pilesfiles", "difficile", "Parenthèses bien formées", "`bien_parenthese(s)` : les `()[]{}` sont-ils bien fermés et imbriqués ? (utilise une pile)", "# Parenthèses bien formées\ndef bien_parenthese(s):\n    pass  # À toi de jouer !\n", "def bien_parenthese(s):\n    pile = []\n    paires = {\")\": \"(\", \"]\": \"[\", \"}\": \"{\"}\n    for c in s:\n        if c in \"([{\":\n            pile.append(c)\n        elif c in paires:\n            if not pile or pile.pop() != paires[c]:\n                return False\n    return not pile", "Empile les ouvrants ; dépile à chaque fermant et compare."], ["g49", "pilesfiles", "difficile", "Notation polonaise inversée", "`eval_rpn(t)` évalue une liste de jetons en notation polonaise inversée (`+ - *`) : `[\"3\",\"4\",\"+\",\"2\",\"*\"]` donne `14`.", "# Notation polonaise inversée\ndef eval_rpn(t):\n    pass  # À toi de jouer !\n", "def eval_rpn(t):\n    pile = []\n    for x in t:\n        if x in (\"+\", \"-\", \"*\"):\n            b, a = pile.pop(), pile.pop()\n            pile.append(a + b if x == \"+\" else a - b if x == \"-\" else a * b)\n        else:\n            pile.append(int(x))\n    return pile[0]", "Nombre : on empile. Opérateur : on dépile deux valeurs."], ["g50", "problemes", "difficile", "Deux sommes", "`deux_sommes(l, cible)` retourne `[i, j]` (i < j) tels que `l[i] + l[j] == cible`, sinon `[]`.", "# Deux sommes\ndef deux_sommes(l, cible):\n    pass  # À toi de jouer !\n", "def deux_sommes(l, cible):\n    vus = {}\n    for i, x in enumerate(l):\n        if cible - x in vus:\n            return [vus[cible - x], i]\n        vus[x] = i\n    return []", "Un dictionnaire `valeur → indice` évite la double boucle."], ["g51", "problemes", "difficile", "Élément majoritaire", "`majoritaire(l)` : valeur présente plus de `len(l)/2` fois, sinon `-1`.", "# Élément majoritaire\ndef majoritaire(l):\n    pass  # À toi de jouer !\n", "def majoritaire(l):\n    c = {}\n    for x in l:\n        c[x] = c.get(x, 0) + 1\n        if c[x] > len(l) / 2:\n            return x\n    return -1", "Compte avec un dictionnaire."], ["g52", "problemes", "difficile", "Sous-chaîne sans répétition", "`longueur_sans_repetition(s)` : longueur de la plus longue sous-chaîne sans lettre répétée.", "# Sous-chaîne sans répétition\ndef longueur_sans_repetition(s):\n    pass  # À toi de jouer !\n", "def longueur_sans_repetition(s):\n    vus = {}\n    debut = best = 0\n    for i, c in enumerate(s):\n        if c in vus and vus[c] >= debut:\n            debut = vus[c] + 1\n        vus[c] = i\n        best = max(best, i - debut + 1)\n    return best", "Fenêtre glissante : mémorise la dernière position de chaque lettre."], ["b1", "bases", "debutant", "Bonjour !", "Affiche le texte `Bonjour !` avec `print`.", "# Écris ton code ici\n", "print(\"Bonjour !\")", "Le texte va entre guillemets : `print(\"...\")`."], ["b2", "bases", "debutant", "Deux lignes", "Affiche `Salut` puis `Ça va ?`, chacun sur sa ligne.", "# Écris ton code ici\n", "print(\"Salut\")\nprint(\"Ça va ?\")", "Un `print` par ligne."], ["b3", "bases", "debutant", "Afficher un nombre", "Affiche le nombre `2026` (sans guillemets).", "# Écris ton code ici\n", "print(2026)", "Un nombre ne prend pas de guillemets."], ["b4", "bases", "debutant", "Python calcule", "Affiche le résultat de `12 * 5` en laissant Python faire le calcul.", "# Écris ton code ici\n", "print(12 * 5)", "`print(12 * 5)` affiche `60`."], ["b5", "bases", "debutant", "Plusieurs valeurs", "Affiche `J'ai 15 ans` avec un seul `print` à trois valeurs séparées par des virgules : `\"J'ai\"`, `15`, `\"ans\"`.", "# Écris ton code ici\n", "print(\"J'ai\", 15, \"ans\")", "`print` met un espace entre les valeurs."], ["b6", "bases", "debutant", "Un rectangle", "Affiche un rectangle de 3 lignes de 5 étoiles (`*****`).", "# Écris ton code ici\n", "print(\"*****\")\nprint(\"*****\")\nprint(\"*****\")", "Trois `print` identiques."], ["b7", "bases", "debutant", "Un escalier", "Affiche `*`, puis `**`, puis `***`, chacun sur sa ligne.", "# Écris ton code ici\n", "print(\"*\")\nprint(\"**\")\nprint(\"***\")", "Chaque ligne a une étoile de plus."], ["b8", "bases", "debutant", "Ma première variable", "Crée une variable `prix` égale à `12`, puis affiche-la.", "# Écris ton code ici\n", "prix = 12\nprint(prix)", "`prix = 12` stocke la valeur ; `print(prix)` l'affiche."], ["b9", "bases", "debutant", "Somme de deux variables", "`a` et `b` sont définies. Affiche leur somme.", "a = 7\nb = 5\n\n# Écris ton code ici\n", "print(a + b)", "Ton code doit marcher quelles que soient les valeurs de `a` et `b`."], ["b10", "bases", "debutant", "Aire d'un rectangle", "`largeur` et `hauteur` sont définies. Affiche l'aire.", "largeur = 6\nhauteur = 4\n\n# Écris ton code ici\n", "print(largeur * hauteur)", "Aire = largeur × hauteur."], ["b11", "bases", "debutant", "Une phrase personnalisée", "`nom` est définie. Affiche `Bonjour <nom> !`, par exemple `Bonjour Ada !`.", "nom = 'Ada'\n\n# Écris ton code ici\n", "print(\"Bonjour\", nom, \"!\")", "`print(\"Bonjour\", nom, \"!\")` ou une f-string : `f\"Bonjour {nom} !\"`."], ["b12", "bases", "debutant", "Échanger deux variables", "`a` et `b` sont définies. Échange leurs contenus, puis affiche `a`, puis `b` (une valeur par ligne).", "a = 1\nb = 2\n\n# Écris ton code ici\n", "a, b = b, a\nprint(a)\nprint(b)", "Python permet `a, b = b, a`."], ["b13", "bases", "debutant", "Quotient et reste", "`n` est définie. Affiche `n // 5` puis `n % 5` (deux lignes).", "n = 17\n\n# Écris ton code ici\n", "print(n // 5)\nprint(n % 5)", "`//` donne le quotient, `%` le reste."], ["b14", "bases", "debutant", "Puissance", "Affiche `3` puissance `4` avec l'opérateur `**`.", "# Écris ton code ici\n", "print(3 ** 4)", "`a ** b` calcule `a` puissance `b`."], ["b15", "bases", "debutant", "Minutes et secondes", "`secondes` est définie. Affiche par exemple `2 min 15 s` pour 135.", "secondes = 135\n\n# Écris ton code ici\n", "print(secondes // 60, \"min\", secondes % 60, \"s\")", "Minutes = `secondes // 60`, reste = `secondes % 60`."], ["b16", "bases", "debutant", "Moyenne de trois notes", "`a`, `b`, `c` sont définies. Affiche leur moyenne (avec `/`).", "a = 12\nb = 15\nc = 9\n\n# Écris ton code ici\n", "print((a + b + c) / 3)", "N'oublie pas les parenthèses autour de la somme."], ["b17", "bases", "debutant", "Majeur ou mineur", "`age` est définie. Affiche `majeur` si `age >= 18`, sinon `mineur`.", "age = 17\n\n# Écris ton code ici\n", "if age >= 18:\n    print(\"majeur\")\nelse:\n    print(\"mineur\")", "`if … :` puis `else:` ; n'oublie pas l'indentation."], ["b18", "bases", "debutant", "Pair ou impair", "`n` est définie. Affiche `pair` ou `impair`.", "n = 4\n\n# Écris ton code ici\n", "if n % 2 == 0:\n    print(\"pair\")\nelse:\n    print(\"impair\")", "Un nombre est pair si `n % 2 == 0`."], ["b19", "bases", "debutant", "Positif, négatif ou nul", "`n` est définie. Affiche `positif`, `négatif` ou `nul`.", "n = 5\n\n# Écris ton code ici\n", "if n > 0:\n    print(\"positif\")\nelif n < 0:\n    print(\"négatif\")\nelse:\n    print(\"nul\")", "`elif` ajoute un cas intermédiaire."], ["b20", "bases", "debutant", "Le plus grand", "`a` et `b` sont définies. Affiche la plus grande valeur (sans `max`).", "a = 3\nb = 9\n\n# Écris ton code ici\n", "if a > b:\n    print(a)\nelse:\n    print(b)", "Compare `a` et `b`."], ["b21", "bases", "intermediaire", "Mention au bac", "`note` est définie. Affiche `TB` (≥ 16), `B` (≥ 14), `AB` (≥ 12), `Passable` (≥ 10), sinon `Refusé`.", "note = 17\n\n# Écris ton code ici\n", "if note >= 16:\n    print(\"TB\")\nelif note >= 14:\n    print(\"B\")\nelif note >= 12:\n    print(\"AB\")\nelif note >= 10:\n    print(\"Passable\")\nelse:\n    print(\"Refusé\")", "Commence par la note la plus haute : les `elif` s'enchaînent."], ["b22", "bases", "debutant", "Répéter", "Affiche `Bravo !` trois fois, avec une boucle `for`.", "# Écris ton code ici\n", "for i in range(3):\n    print(\"Bravo !\")", "`for i in range(3):` répète 3 fois."], ["b23", "bases", "debutant", "Compter de 1 à n", "`n` est définie. Affiche les nombres de `1` à `n`, un par ligne.", "n = 5\n\n# Écris ton code ici\n", "for i in range(1, n + 1):\n    print(i)", "`range(1, n + 1)` s'arrête avant `n + 1`."], ["b24", "bases", "debutant", "Compte à rebours", "Affiche `10`, `9`, …, `1` (un par ligne), puis `Décollage !`.", "# Écris ton code ici\n", "for i in range(10, 0, -1):\n    print(i)\nprint(\"Décollage !\")", "`range(10, 0, -1)` descend de 10 à 1."], ["b25", "bases", "debutant", "Somme de 1 à n", "`n` est définie. Affiche `1 + 2 + … + n`, avec une boucle.", "n = 10\n\n# Écris ton code ici\n", "t = 0\nfor i in range(1, n + 1):\n    t += i\nprint(t)", "Une variable `t` qui accumule, initialisée à 0."], ["b26", "bases", "debutant", "Les nombres pairs", "Affiche les nombres pairs de `2` à `20` inclus, un par ligne.", "# Écris ton code ici\n", "for i in range(2, 21, 2):\n    print(i)", "Le 3e argument de `range` est le pas."], ["b27", "bases", "intermediaire", "Les carrés", "Affiche les carrés de `1` à `5` (`1`, `4`, `9`, `16`, `25`), un par ligne.", "# Écris ton code ici\n", "for i in range(1, 6):\n    print(i * i)", "Le carré de `i` est `i * i`."], ["b28", "bases", "intermediaire", "Triangle d'étoiles", "`n` est définie. Affiche `n` lignes ; la ligne `i` contient `i` étoiles.", "n = 3\n\n# Écris ton code ici\n", "for i in range(1, n + 1):\n    print(\"*\" * i)", "`\"*\" * 3` donne `***`."], ["b29", "bases", "intermediaire", "Premier doublement", "Pars de `x = 1` et double-le tant que `x < 1000`. Affiche la valeur finale de `x`.", "# Écris ton code ici\n", "x = 1\nwhile x < 1000:\n    x = x * 2\nprint(x)", "`while x < 1000:` s'arrête dès que la condition devient fausse."], ["b30", "bases", "intermediaire", "Nombre de chiffres", "`n` (entier > 0) est définie. Affiche son nombre de chiffres, avec un `while`.", "n = 5\n\n# Écris ton code ici\n", "c = 0\nwhile n > 0:\n    n = n // 10\n    c += 1\nprint(c)", "Divise `n` par 10 jusqu'à 0 en comptant les étapes."], ["b31", "bases", "intermediaire", "Plus petite puissance de 2", "`n` est définie. Affiche le plus petit `k` tel que `2 ** k >= n`.", "n = 1000\n\n# Écris ton code ici\n", "k = 0\nwhile 2 ** k < n:\n    k += 1\nprint(k)", "Incrémente `k` tant que `2 ** k` est trop petit."], ["b32", "bases", "debutant", "Dire bonjour", "Définis une fonction `dire_bonjour()` qui affiche `Bonjour !`, puis appelle-la deux fois.", "# Écris ton code ici\n", "def dire_bonjour():\n    print(\"Bonjour !\")\n\ndire_bonjour()\ndire_bonjour()", "`def nom():` + corps indenté ; on l'appelle avec `nom()`."], ["c1", "bases", "debutant", "Saluer", "Écris `saluer(nom)` qui RETOURNE (avec `return`) la chaîne `Bonjour <nom> !`.", "# Saluer\ndef saluer(nom):\n    pass  # À toi de jouer !\n", "def saluer(nom):\n    return \"Bonjour \" + nom + \" !\"", "`return` renvoie une valeur ; `print` ne fait que l'afficher."], ["c2", "bases", "debutant", "Triple", "`triple(n)` retourne le triple de `n`.", "# Triple\ndef triple(n):\n    pass  # À toi de jouer !\n", "def triple(n):\n    return 3 * n", "Une fonction qui calcule et retourne."], ["c3", "bases", "debutant", "Addition", "`addition(a, b)` retourne la somme de ses deux paramètres.", "# Addition\ndef addition(a, b):\n    pass  # À toi de jouer !\n", "def addition(a, b):\n    return a + b", "Deux paramètres séparés par une virgule."]];

